package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;

/**
 * Error response body for a rejected owner create: {@code {"errors": ["city", ...]}}.
 *
 * <p>This is a deliberate, spec-mandated divergence from the project's usual
 * {@link org.springframework.http.ProblemDetail} error contract: the create endpoint's
 * specification requires a top-level {@code errors} array naming each missing or blank
 * required field, which {@code ProblemDetail} (and its {@code schemaValidationErrors})
 * does not express.
 */
public class OwnerFieldErrors {

    private final List<String> errors;

    public OwnerFieldErrors(List<String> errors) {
        this.errors = errors;
    }

    public List<String> getErrors() {
        return this.errors;
    }
}
===InvalidPostcodeExceptionHandler===
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.function.owner.InvalidPostcodeException;

/**
 * Responds 400 when an owner create request's supplied {@code postcode} is not four digits or is
 * out of range for the city's region. Mirrors the create endpoint's {@code errors} array contract
 * ({@link OwnerFieldErrors}) used for missing/blank and other invalid fields, naming
 * {@code postcode}.
 */
public class InvalidPostcodeExceptionHandler {

    public void handle(@Parameter InvalidPostcodeException ex,
            ObjectResponse<ResponseEntity<OwnerFieldErrors>> response) {
        response.send(ResponseEntity.badRequest().body(new OwnerFieldErrors(List.of("postcode"))));
    }
}
===InvalidPostcodeException===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link ValidateOwnerPostcode} when an owner create request carries a {@code postcode}
 * that is present but invalid: either not four digits, or outside the inclusive range for the
 * city's known region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
 * accepts any 4-digit postcode. Checked so it appears in the {@code throws} clause and is routed
 * to its escalation handler, which responds 400.
 */
public class InvalidPostcodeException extends Exception {

    public InvalidPostcodeException(String postcode) {
        super("Postcode is not valid for the owner's city: " + postcode);
    }
}

